dashboard.definition:
{
 "title": "Switch Details",
 "description": "One switch: ports, CPU, memory, PoE, traffic, errors, CDP neighbours, MAC table and syslog. Covers Cribl (sw11-13) and gnmic (IOS-XE, NX-OS) telemetry.",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-4h@m,now"
   }
  },
  "input_node": {
   "type": "input.dropdown",
   "title": "Device",
   "dataSources": {
    "primary": "ds_nodes"
   },
   "options": {
    "token": "tk_node",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"node\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"node\") | renameSeries(\"value\")"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "90s",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_ports": {
   "type": "mdt_infra_monitoring.port_faceplate",
   "title": "Ports. Click a port to open its details.",
   "dataSources": {
    "primary": "ds_ports"
   },
   "options": {},
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/mdt_infra_monitoring/interface_details?form.tk_node=$tk_node$&form.tk_interface=$click.value$&form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
      "newTab": true
     }
    }
   ]
  },
  "viz_nodata": {
   "type": "splunk.table",
   "dataSources": {
    "primary": "ds_nodata"
   },
   "options": {},
   "containerOptions": {
    "visibility": {
     "hideWhenNoData": true
    }
   }
  },
  "viz_cpu": {
   "type": "splunk.markergauge",
   "title": "CPU %",
   "dataSources": {
    "primary": "ds_cpu"
   },
   "options": {
    "orientation": "horizontal",
    "gaugeRanges": [
     {
      "from": 0,
      "to": 70,
      "value": "#53a051"
     },
     {
      "from": 70,
      "to": 90,
      "value": "#f8be34"
     },
     {
      "from": 90,
      "to": 100,
      "value": "#dc4e41"
     }
    ]
   }
  },
  "viz_mem": {
   "type": "splunk.markergauge",
   "title": "Memory %",
   "dataSources": {
    "primary": "ds_mem"
   },
   "options": {
    "orientation": "horizontal",
    "gaugeRanges": [
     {
      "from": 0,
      "to": 70,
      "value": "#53a051"
     },
     {
      "from": 70,
      "to": 90,
      "value": "#f8be34"
     },
     {
      "from": 90,
      "to": 100,
      "value": "#dc4e41"
     }
    ]
   }
  },
  "viz_poe": {
   "type": "splunk.markergauge",
   "title": "PoE drawn (% of PoE capacity)",
   "dataSources": {
    "primary": "ds_poe_gauge"
   },
   "options": {
    "orientation": "horizontal",
    "gaugeRanges": [
     {
      "from": 0,
      "to": 70,
      "value": "#53a051"
     },
     {
      "from": 70,
      "to": 90,
      "value": "#f8be34"
     },
     {
      "from": 90,
      "to": 100,
      "value": "#dc4e41"
     }
    ]
   },
   "containerOptions": {
    "visibility": {
     "hideWhenNoData": true
    }
   }
  },
  "viz_ports_up": {
   "type": "splunk.markergauge",
   "title": "Ports up %",
   "dataSources": {
    "primary": "ds_ports_up"
   },
   "options": {
    "orientation": "horizontal",
    "gaugeRanges": [
     {
      "from": 0,
      "to": 100,
      "value": "#708794"
     }
    ]
   }
  },
  "viz_throughput": {
   "type": "splunk.line",
   "title": "Throughput, sum of all ports (5 min average)",
   "dataSources": {
    "primary": "ds_throughput"
   },
   "options": {},
   "showProgressBar": true
  },
  "viz_errors": {
   "type": "splunk.column",
   "title": "Errors per 5 min (all ports)",
   "dataSources": {
    "primary": "ds_errors"
   },
   "options": {
    "stackMode": "stacked"
   },
   "showProgressBar": true
  },
  "viz_top_util": {
   "type": "splunk.bar",
   "title": "Top 5 interfaces by peak utilization % (in or out); click to open",
   "dataSources": {
    "primary": "ds_top_util"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true,
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/mdt_infra_monitoring/interface_details?form.tk_node=$tk_node$&form.tk_interface=$row.interface.value$&form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
      "newTab": true
     }
    }
   ]
  },
  "viz_top_errors": {
   "type": "splunk.bar",
   "title": "Top 5 interfaces with errors; click to open",
   "dataSources": {
    "primary": "ds_top_errors"
   },
   "options": {
    "stackMode": "stacked",
    "legendDisplay": "bottom"
   },
   "showProgressBar": true,
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/mdt_infra_monitoring/interface_details?form.tk_node=$tk_node$&form.tk_interface=$row.interface.value$&form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
      "newTab": true
     }
    }
   ]
  },
  "viz_ifaces": {
   "type": "splunk.table",
   "title": "Interfaces; click a row to open",
   "dataSources": {
    "primary": "ds_ifaces_table"
   },
   "options": {
    "count": 100
   },
   "showProgressBar": true,
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/mdt_infra_monitoring/interface_details?form.tk_node=$tk_node$&form.tk_interface=$row.Interface.value$&form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
      "newTab": true
     }
    }
   ]
  },
  "viz_mac": {
   "type": "splunk.table",
   "title": "MAC addresses on port-channels and VLANs",
   "dataSources": {
    "primary": "ds_mac"
   },
   "options": {
    "count": 50
   },
   "showProgressBar": true,
   "containerOptions": {
    "visibility": {
     "hideWhenNoData": true
    }
   }
  },
  "viz_logs": {
   "type": "splunk.table",
   "title": "Syslog",
   "dataSources": {
    "primary": "ds_logs"
   },
   "options": {
    "count": 50
   },
   "showProgressBar": true
  }
 },
 "dataSources": {
  "ds_nodes": {
   "type": "ds.search",
   "name": "nodes",
   "options": {
    "query": "| `mdt_nodes($global_time.earliest$)`"
   }
  },
  "ds_status": {
   "type": "ds.search",
   "name": "status",
   "options": {
    "query": "| `mdt_if_status($tk_node$)` | join type=left node interface [| `mdt_cdp($tk_node$)` | stats values(neighbour) as neighbour by node interface] | join type=left node interface [| `mdt_mac($tk_node$,*)` | eval entry=mac.if(vlan==\"-\", \"\", \" (VLAN \".vlan.\")\") | stats dc(mac) as macs values(entry) as mac_list by node interface] | eval inorm=`mdt_ifkey(interface)` | join type=left node inorm [| `mdt_poe_port($tk_node$)` | eval inorm=`mdt_ifkey(interface)` | fields node inorm poe_w poe_state pd_class] | join type=left node interface [| `mdt_if_counters($tk_node$,*)` | `mdt_if_rates` | stats sum(in_errs) as in_errs sum(out_errs) as out_errs by node interface | where in_errs + out_errs > 0]"
   }
  },
  "ds_rates": {
   "type": "ds.search",
   "name": "rates",
   "options": {
    "query": "| `mdt_if_counters($tk_node$,*)` | `mdt_physical_ports` | `mdt_if_rates` | join type=left node interface [| `mdt_if_status($tk_node$)` | fields node interface speed] | eval util=round(max(in_bps, out_bps) / speed * 100, 4)"
   }
  },
  "ds_poe": {
   "type": "ds.search",
   "name": "poe",
   "options": {
    "query": "| `mdt_poe($tk_node$)`"
   }
  },
  "ds_cpu": {
   "type": "ds.search",
   "name": "cpu",
   "options": {
    "query": "| `mdt_cpu($tk_node$)` | stats latest(cpu) as cpu | eval cpu=round(cpu, 0)"
   }
  },
  "ds_mem": {
   "type": "ds.search",
   "name": "mem",
   "options": {
    "query": "| `mdt_mem($tk_node$)` | stats latest(mem) as mem | eval mem=round(mem, 0)"
   }
  },
  "ds_mac": {
   "type": "ds.search",
   "name": "mac",
   "options": {
    "query": "| `mdt_mac($tk_node$,*)` | where NOT (`mdt_is_physical`) | sort interface vlan mac | rename interface as Interface, vlan as VLAN, mac as MAC | fields - node"
   }
  },
  "ds_logs": {
   "type": "ds.search",
   "name": "logs",
   "options": {
    "query": "index=cisco_syslog host=\"$tk_node$\" | eval severity=mvindex(severity, 0), message=mvindex(message, 0) | table _time severity message | sort - _time | head 200"
   }
  },
  "ds_ports": {
   "type": "ds.chain",
   "name": "ports",
   "options": {
    "extend": "ds_status",
    "query": "| `mdt_physical_ports` | rex field=interface \"^\\D+(?<path>\\d+(/\\d+)+)\" | sort 0 - oper_up - speed | dedup keepempty=true node path | sort 0 interface | fields - path | rex field=interface \"^\\D+(?<member>\\d+)/\" | join type=left node member [| `mdt_model($tk_node$)` | fields node member model] | fillnull value=\"\" model | eval state=case(admin_up==0, \"admin down\", oper_up==1, \"up\", true(), \"down\") | eval neighbour=mvjoin(neighbour, \", \"), mac_list=mvjoin(mvindex(mac_list, 0, min(4, mvcount(mac_list) - 1)), \", \") | fillnull value=0 macs | fillnull value=\"\" neighbour mac_list | fields interface state speed neighbour macs mac_list poe_w poe_state pd_class in_errs out_errs model"
   }
  },
  "ds_nodata": {
   "type": "ds.chain",
   "name": "nodata",
   "options": {
    "extend": "ds_status",
    "query": "| stats count | where count=0 | eval Note=\"No telemetry for $tk_node$. Switch Details covers switches that stream interface data.\" | fields Note"
   }
  },
  "ds_ports_up": {
   "type": "ds.chain",
   "name": "ports_up",
   "options": {
    "extend": "ds_status",
    "query": "| `mdt_physical_ports` | rex field=interface \"^\\D+(?<path>\\d+(/\\d+)+)\" | sort 0 - oper_up - speed | dedup keepempty=true node path | sort 0 interface | fields - path | stats count as total sum(oper_up) as up | eval pct=round(up / total * 100, 0) | fields pct"
   }
  },
  "ds_ifaces_table": {
   "type": "ds.chain",
   "name": "ifaces_table",
   "options": {
    "extend": "ds_status",
    "query": "| `mdt_physical_ports` | rex field=interface \"^\\D+(?<path>\\d+(/\\d+)+)\" | sort 0 - oper_up - speed | dedup keepempty=true node path | sort 0 interface | fields - path | eval Status=case(admin_up==0, \"admin down\", oper_up==1, \"up\", true(), \"down\") | eval Speed=case(speed >= 1000000000, round(speed / 1000000000, 1).\" Gb/s\", speed > 0, round(speed / 1000000, 0).\" Mb/s\") | eval \"Last change\"=strftime(last_change, \"%Y-%m-%d %H:%M\") | eval d=floor(now() - last_change), dd=floor(d / 86400), dh=floor(d % 86400 / 3600), dm=floor(d % 3600 / 60) | eval \"Down for\"=if(oper_up==0 AND isnotnull(last_change), trim(if(dd > 0, dd.\"d \", \"\").if(dh > 0, dh.\"h \", \"\").if(dm > 0 OR d < 3600, dm.\"m\", \"\")), null()) | eval MACs=case(macs > 5, macs.\" MACs\", macs > 0, mac_list) | fillnull value=\"\" \"Down for\" \"CDP neighbour\" MACs | rename interface as Interface, neighbour as \"CDP neighbour\" | table Interface Status Speed \"Last change\" \"Down for\" \"CDP neighbour\" MACs"
   }
  },
  "ds_poe_gauge": {
   "type": "ds.chain",
   "name": "poe_gauge",
   "options": {
    "extend": "ds_poe",
    "query": "| eval pct=round(used / (used + free) * 100, 0) | fields pct"
   }
  },
  "ds_throughput": {
   "type": "ds.chain",
   "name": "throughput",
   "options": {
    "extend": "ds_rates",
    "query": "| bin _time span=5m | where _time + 300 <= now() | stats avg(in_bps) as in avg(out_bps) as out by _time interface | stats sum(in) as in sum(out) as out by _time | eval \"In (Mb/s)\"=round(in / 1000000, 2), \"Out (Mb/s)\"=round(out / 1000000, 2) | fields - in out"
   }
  },
  "ds_errors": {
   "type": "ds.chain",
   "name": "errors",
   "options": {
    "extend": "ds_rates",
    "query": "| bin _time span=5m | where _time + 300 <= now() | timechart span=5m sum(in_errs) as \"In errors\" sum(out_errs) as \"Out errors\""
   }
  },
  "ds_top_util": {
   "type": "ds.chain",
   "name": "top_util",
   "options": {
    "extend": "ds_rates",
    "query": "| stats max(util) as \"Peak utilization %\" by interface | sort - \"Peak utilization %\" | head 5"
   }
  },
  "ds_top_errors": {
   "type": "ds.chain",
   "name": "top_errors",
   "options": {
    "extend": "ds_rates",
    "query": "| stats sum(in_errs) as \"In errors\" sum(out_errs) as \"Out errors\" by interface | eval total='In errors' + 'Out errors' | where total > 0 | sort - total | head 5 | fields - total"
   }
  }
 },
 "layout": {
  "type": "grid",
  "globalInputs": [
   "input_time",
   "input_node"
  ],
  "layoutDefinitions": {
   "layout_1": {
    "type": "grid",
    "options": {
     "width": 1440,
     "height": 1960
    },
    "structure": [
     {
      "item": "viz_nodata",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 1440,
       "h": 80
      }
     },
     {
      "item": "viz_cpu",
      "type": "block",
      "position": {
       "x": 0,
       "y": 80,
       "w": 360,
       "h": 200
      }
     },
     {
      "item": "viz_mem",
      "type": "block",
      "position": {
       "x": 360,
       "y": 80,
       "w": 360,
       "h": 200
      }
     },
     {
      "item": "viz_poe",
      "type": "block",
      "position": {
       "x": 720,
       "y": 80,
       "w": 360,
       "h": 200
      }
     },
     {
      "item": "viz_ports_up",
      "type": "block",
      "position": {
       "x": 1080,
       "y": 80,
       "w": 360,
       "h": 200
      }
     },
     {
      "item": "viz_ports",
      "type": "block",
      "position": {
       "x": 0,
       "y": 280,
       "w": 1440,
       "h": 200
      }
     },
     {
      "item": "viz_top_util",
      "type": "block",
      "position": {
       "x": 0,
       "y": 480,
       "w": 720,
       "h": 260
      }
     },
     {
      "item": "viz_top_errors",
      "type": "block",
      "position": {
       "x": 720,
       "y": 480,
       "w": 720,
       "h": 260
      }
     },
     {
      "item": "viz_throughput",
      "type": "block",
      "position": {
       "x": 0,
       "y": 740,
       "w": 720,
       "h": 320
      }
     },
     {
      "item": "viz_errors",
      "type": "block",
      "position": {
       "x": 720,
       "y": 740,
       "w": 720,
       "h": 320
      }
     },
     {
      "item": "viz_ifaces",
      "type": "block",
      "position": {
       "x": 0,
       "y": 1060,
       "w": 940,
       "h": 480
      }
     },
     {
      "item": "viz_mac",
      "type": "block",
      "position": {
       "x": 940,
       "y": 1060,
       "w": 500,
       "h": 480
      }
     },
     {
      "item": "viz_logs",
      "type": "block",
      "position": {
       "x": 0,
       "y": 1540,
       "w": 1440,
       "h": 420
      }
     }
    ]
   }
  },
  "tabs": {
   "items": [
    {
     "label": "Switch",
     "layoutId": "layout_1"
    }
   ]
  }
 },
 "applicationProperties": {}
}
